-- The entry kind of retired slugs, and a corrected backfill (ADR 0003).
-- Generated by Drizzle Kit; the two backfill UPDATEs were added by hand for
-- databases that applied 0002 to rows written before it. On a database
-- created from these migrations they change nothing.
--
-- Backfill: every slug of an entry with a currently published version is
-- treated as published, so its public URLs stay reserved and keep
-- redirecting (0002 covered only entries with entries.first_published_at).
UPDATE "entry_slugs" SET "was_published" = true FROM "entry_texts" WHERE "entry_texts"."entry_id" = "entry_slugs"."entry_id" AND "entry_texts"."status" = 'published';--> statement-breakpoint
-- Backfill: the entry's first publication is no later than the earliest
-- recorded first publication of its versions. Rows from before 0002 may keep
-- an earlier entry-level value for which no version history was recorded.
UPDATE "entries" SET "first_published_at" = least("entries"."first_published_at", "history"."earliest") FROM (SELECT "entry_id", min("first_published_at") AS "earliest" FROM "entry_texts" GROUP BY "entry_id") AS "history" WHERE "history"."entry_id" = "entries"."id" AND "history"."earliest" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "entry_slugs" ADD CONSTRAINT "entry_slugs_kind_check" CHECK (kind in ('album_journal', 'artist_journal', 'memory'));